326:   static void Convert (napi_env env, const std::string* s, bool asBuffer, napi_value* result) {
327:     if (s == NULL) {
328:       napi_get_undefined(env, result);
329:     } else if (asBuffer) {
330:       napi_create_buffer_copy(env, s->size(), s->data(), NULL, result);
331:     } else {
332:       napi_create_string_utf8(env, s->data(), s->size(), result);
333:     }
334:   }
335: 
336: private:
337:   std::string* key_;
338:   std::string* value_;
339: };
